content.content:
1	/* ========================================
2	   KOPISOP — 样式表
3	   温暖棕色氛围，舒适，学生友好
4	   ======================================== */
5	
6	/* ---------- RESET & BASE ---------- */
7	*, *::before, *::after {
8	    margin: 0;
9	    padding: 0;
10	    box-sizing: border-box;
11	}
12	
13	html {
14	    scroll-behavior: smooth;
15	    font-size: 16px;
16	}
17	
18	body {
19	    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
20	    background-color: #FDF8F0;
21	    color: #2C1810;
22	    line-height: 1.7;
23	    overflow-x: hidden;
24	}
25	
26	img {
27	    max-width: 100%;
28	    display: block;
29	}
30	
31	a {
32	    text-decoration: none;
33	    color: inherit;
34	    transition: color 0.3s ease;
35	}
36	
37	ul {
38	    list-style: none;
39	}
40	
41	/* ---------- TYPOGRAPHY ---------- */
42	h1, h2, h3, h4 {
43	    font-family: 'Playfair Display', Georgia, serif;
44	    font-weight: 600;
45	    line-height: 1.3;
46	}
47	
48	/* ---------- CONTAINER ---------- */
49	.container {
50	    max-width: 1140px;
51	    margin: 0 auto;
52	    padding: 0 1.5rem;
53	}
54	
55	/* ---------- BUTTONS ---------- */
56	.btn {
57	    display: inline-flex;
58	    align-items: center;
59	    gap: 0.5rem;
60	    padding: 0.85rem 2rem;
61	    border-radius: 50px;
62	    font-family: 'Inter', sans-serif;
63	    font-weight: 500;
64	    font-size: 0.95rem;
65	    cursor: pointer;
66	    transition: all 0.3s ease;
67	    border: 2px solid transparent;
68	}
69	
70	.btn-primary {
71	    background: #6B4226;
72	    color: #fff;
73	    border-color: #6B4226;
74	}
75	
76	.btn-primary:hover {
77	    background: #5D3A1A;
78	    border-color: #5D3A1A;
79	    transform: translateY(-2px);
80	    box-shadow: 0 6px 20px rgba(107, 66, 38, 0.3);
81	}
82	
83	.btn-outline {
84	    background: transparent;
85	    color: #6B4226;
86	    border-color: #6B4226;
87	}
88	
89	.btn-outline:hover {
90	    background: #6B4226;
91	    color: #fff;
92	    transform: translateY(-2px);
93	    box-shadow: 0 6px 20px rgba(107, 66, 38, 0.2);
94	}
95	
96	.btn-full {
97	    width: 100%;
98	    justify-content: center;
99	}
100	
101	/* ---------- SECTION (base) ---------- */
102	.section {
103	    padding: 6rem 0;
104	    position: relative;
105	    z-index: 1;
106	}
107	
108	/* ---------- STICKY SECTION LAYOUT ----------
109	   Each section "sticks" as you scroll past,
110	   creating a stacking card effect.
111	   Hero stays as full-page cover, then sections stack.
112	-------------------------------------------------*/
113	.sticky-section {
114	    position: sticky;
115	    top: 0;
116	    height: 100vh;
117	    display: flex;
118	    align-items: center;
119	    overflow: hidden;
120	}
121	.sticky-section .container {
122	    width: 100%;
123	    max-height: 100vh;
124	    overflow-y: auto;
125	    padding: 4rem 1.5rem;
126	    box-sizing: border-box;
127	}
128	
129	/* Subtle shadow on each sticky section for depth */
130	.sticky-section::after {
131	    content: '';
132	    position: absolute;
133	    bottom: -2px;
134	    left: 0;
135	    width: 100%;
136	    height: 4px;
137	    background: linear-gradient(90deg, transparent, rgba(198, 134, 66, 0.2), transparent);
138	    z-index: 10;
139	}
140	
141	/* Z-index stacking for sticky sections (in DOM order) */
142	.sticky-section:nth-of-type(1) { z-index: 1; }
143	.sticky-section:nth-of-type(2) { z-index: 2; }
144	.sticky-section:nth-of-type(3) { z-index: 3; }
145	.sticky-section:nth-of-type(4) { z-index: 4; }
146	.sticky-section:nth-of-type(5) { z-index: 5; }
147	
148	/* Alternate background for sticky sections */
149	.sticky-section:nth-of-type(even) {
150	    background-color: #F5E6D3;
151	}
152	.sticky-section:nth-of-type(odd) {
153	    background-color: #FDF8F0;
154	}
155	
156	/* Remove old section overlap and z-index rules */
157	/* .section + .section { margin-top: -6rem; } */
158	/* .section:nth-child(2) { z-index: 2; } ... etc */
159	
160	.section-header {
161	    text-align: center;
162	    margin-bottom: 3.5rem;
163	}
164	
165	.section-label {
166	    display: inline-block;
167	    font-size: 0.8rem;
168	    font-weight: 500;
169	    letter-spacing: 3px;
170	    text-transform: uppercase;
171	    color: #C68642;
172	    margin-bottom: 0.75rem;
173	}
174	
175	.section-title {
176	    font-size: 2.2rem;
177	    color: #2C1810;
178	    margin-bottom: 0.75rem;
179	}
180	
181	.section-divider {
182	    width: 50px;
183	    height: 3px;
184	    background: #C68642;
185	    margin: 0 auto;
186	    border-radius: 2px;
187	}
188	
189	.section-desc {
190	    color: #7D6B5A;
191	    max-width: 500px;
192	    margin: 1rem auto 0;
193	    font-size: 1rem;
194	}
195	
196	/* ---------- SCROLL REVEAL ---------- */
197	.reveal {
198	    opacity: 0;
199	    transform: translateY(40px) scale(0.97);
200	    transition: opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94),
201	                transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94);
202	}
203	
204	.reveal.visible {
205	    opacity: 1;
206	    transform: translateY(0) scale(1);
207	}
208	
209	/* Stagger delays for children */
210	.reveal-stagger > *:nth-child(1) { transition-delay: 0s; }
211	.reveal-stagger > *:nth-child(2) { transition-delay: 0.1s; }
212	.reveal-stagger > *:nth-child(3) { transition-delay: 0.2s; }
213	.reveal-stagger > *:nth-child(4) { transition-delay: 0.3s; }
214	
215	/* Slide direction variants */
216	.reveal-left {
217	    opacity: 0;
218	    transform: translateX(-50px);
219	    transition: opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94),
220	                transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94);
221	}
222	.reveal-left.visible {
223	    opacity: 1;
224	    transform: translateX(0);
225	}
226	
227	.reveal-right {
228	    opacity: 0;
229	    transform: translateX(50px);
230	    transition: opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94),
231	                transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94);
232	}
233	.reveal-right.visible {
234	    opacity: 1;
235	    transform: translateX(0);
236	}
237	
238	.reveal-scale {
239	    opacity: 0;
240	    transform: scale(0.85);
241	    transition: opacity 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275),
242	                transform 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275);
243	}
244	.reveal-scale.visible {
245	    opacity: 1;
246	    transform: scale(1);
247	}
248	
249	/* Smooth image reveal */
250	.reveal-img {
251	    clip-path: inset(0 0 100% 0);
252	    transition: clip-path 1.2s cubic-bezier(0.25, 0.46, 0.45, 0.94);
253	}
254	.reveal-img.visible {
255	    clip-path: inset(0 0 0 0);
256	}
257	
258	/* Glow effect on visible elements */
259	.reveal.visible,
260	.reveal-left.visible,
261	.reveal-right.visible,
262	.reveal-scale.visible {
263	    animation: glowPulse 3s ease-in-out 1;
264	}
265	@keyframes glowPulse {
266	    0% { filter: brightness(1); }
267	    50% { filter: brightness(1.03); }
268	    100% { filter: brightness(1); }
269	}
270	
271	/* =========================================
272	   SCROLL PROGRESS BAR
273	   ========================================= */
274	.scroll-progress {
275	    position: fixed;
276	    top: 0;
277	    left: 0;
278	    width: 100%;
279	    height: 3px;
280	    z-index: 9999;
281	    background: transparent;
282	}
283	.scroll-progress-bar {
284	    height: 100%;
285	    width: 0%;
286	    background: linear-gradient(90deg, #C68642, #8B5E3C, #6B4226);
287	    transition: width 0.1s linear;
288	    border-radius: 0 2px 2px 0;
289	    box-shadow: 0 0 8px rgba(198, 134, 66, 0.4);
290	}
291	
292	/* Hover magnetic pull for cards */
293	.service-card {
294	    will-change: transform;
295	    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275),
296	                box-shadow 0.4s ease,
297	                border-color 0.4s ease;
298	}
299	.service-card:hover {
300	    transform: translateY(-8px) scale(1.02);
301	    box-shadow: 0 16px 40px rgba(44, 24, 16, 0.15);
302	}
303	
304	/* ========================================
305	   NAVIGASI
306	   ======================================== */
307	.navbar {
308	    position: fixed;
309	    top: 0;
310	    left: 0;
311	    width: 100%;
312	    z-index: 1000;
313	    padding: 1rem 0;
314	    transition: all 0.4s ease;
315	    background: transparent;
316	}
317	
318	.navbar.scrolled {
319	    background: rgba(253, 248, 240, 0.95);
320	    backdrop-filter: blur(12px);
321	    -webkit-backdrop-filter: blur(12px);
322	    box-shadow: 0 2px 20px rgba(44, 24, 16, 0.08);
323	    padding: 0.7rem 0;
324	}
325	
326	.nav-container {
327	    display: flex;
328	    justify-content: space-between;
329	    align-items: center;
330	}
331	
332	.nav-logo {
333	    font-family: 'Playfair Display', serif;
334	    font-size: 1.4rem;
335	    font-weight: 700;
336	    color: #FDF8F0;
337	    display: flex;
338	    align-items: center;
339	    gap: 0.5rem;
340	    transition: color 0.3s ease;
341	}
342	
343	.nav-logo i {
344	    font-size: 1.2rem;
345	}
346	
347	.navbar.scrolled .nav-logo {
348	    color: #6B4226;
349	}
350	
351	.nav-menu {
352	    display: flex;
353	    gap: 2rem;
354	}
355	
356	.nav-link {
357	    font-size: 0.9rem;
358	    font-weight: 400;
359	    color: rgba(253, 248, 240, 0.85);
360	    position: relative;
361	    padding: 0.25rem 0;
362	    transition: color 0.3s ease;
363	}
364	
365	.nav-link::after {
366	    content: '';
367	    position: absolute;
368	    bottom: -2px;
369	    left: 0;
370	    width: 0;
371	    height: 2px;
372	    background: #C68642;
373	    transition: width 0.3s ease;
374	}
375	
376	.nav-link:hover {
377	    color: #fff;
378	}
379	
380	.nav-link:hover::after {
381	    width: 100%;
382	}
383	
384	.navbar.scrolled .nav-link {
385	    color: #7D6B5A;
386	}
387	
388	.navbar.scrolled .nav-link:hover {
389	    color: #6B4226;
390	}
391	
392	.navbar.scrolled .nav-link::after {
393	    background: #6B4226;
394	}
395	
396	/* Toggle button (hamburger) */
397	.nav-toggle {
398	    display: none;
399	    flex-direction: column;
400	    gap: 5px;
401	    background: none;
402	    border: none;
403	    cursor: pointer;
404	    padding: 0.5rem;
405	}
406	
407	.nav-toggle span {
408	    display: block;
409	    width: 24px;
410	    height: 2px;
411	    background: #FDF8F0;
412	    border-radius: 2px;
413	    transition: all 0.3s ease;
414	}
415	
416	.navbar.scrolled .nav-toggle span {
417	    background: #6B4226;
418	}
419	
420	.nav-toggle.active span:nth-child(1) {
421	    transform: rotate(45deg) translate(5px, 5px);
422	}
423	
424	.nav-toggle.active span:nth-child(2) {
425	    opacity: 0;
426	}
427	
428	.nav-toggle.active span:nth-child(3) {
429	    transform: rotate(-45deg) translate(5px, -5px);
430	}
431	
432	/* ========================================
433	   HERO
434	   ======================================== */
435	.hero {
436	    position: relative;
437	    min-height: 100vh;
438	    display: flex;
439	    align-items: center;
440	    overflow: hidden;
441	}
442	
443	.hero-bg {
444	    position: absolute;
445	    inset: 0;
446	    background-size: cover;
447	    background-position: center;
448	    z-index: 0;
449	    will-change: transform;
450	}
451	
452	/* Gradient overlay on hero background image */
453	.hero-bg::before {
454	    content: '';
455	    position: absolute;
456	    inset: 0;
457	    background: linear-gradient(135deg, rgba(44, 24, 16, 0.35) 0%, rgba(93, 58, 26, 0.2) 40%, rgba(107, 66, 38, 0.1) 100%);
458	}
459	
460	.hero-overlay {
461	    position: absolute;
462	    inset: 0;
463	    background: linear-gradient(to right, rgba(44, 24, 16, 0.25) 0%, rgba(44, 24, 16, 0.05) 100%);
464	    z-index: 1;
465	}
466	
467	.hero-content {
468	    position: relative;
469	    z-index: 2;
470	    display: grid;
471	    grid-template-columns: 1fr 1fr;
472	    gap: 3rem;
473	    align-items: center;
474	    padding-top: 5rem;
475	}
476	
477	.hero-text {
478	    color: #FDF8F0;
479	}
480	
481	.hero-badge {
482	    display: inline-block;
483	    font-size: 0.8rem;
484	    letter-spacing: 3px;
485	    text-transform: uppercase;
486	    color: #D4A56A;
487	    margin-bottom: 1rem;
488	    font-weight: 400;
489	}
490	
491	.hero-title {
492	    font-size: 4rem;
493	    font-weight: 700;
494	    margin-bottom: 0.75rem;
495	    line-height: 1.1;
496	    color: #fff;
497	    text-shadow: 0 0 30px rgba(212, 165, 106, 0.3);
498	    animation: titleGlow 4s ease-in-out infinite;
499	}
500	
501	@keyframes titleGlow {
502	    0%, 100% { text-shadow: 0 0 20px rgba(212, 165, 106, 0.2); }
503	    50% { text-shadow: 0 0 40px rgba(212, 165, 106, 0.5), 0 0 60px rgba(212, 165, 106, 0.2); }
504	}
505	
506	.hero-tagline {
507	    font-size: 1.2rem;
508	    font-weight: 300;
509	    color: #D4A56A;
510	    margin-bottom: 1rem;
511	}
512	
513	.hero-desc {
514	    font-size: 1rem;
515	    color: rgba(253, 248, 240, 0.7);
516	    margin-bottom: 2rem;
517	    max-width: 450px;
518	}
519	
520	.hero-actions {
521	    display: flex;
522	    gap: 1rem;
523	    flex-wrap: wrap;
524	}
525	
526	.hero-actions .btn-outline {
527	    color: #FDF8F0;
528	    border-color: rgba(253, 248, 240, 0.4);
529	}
530	
531	.hero-actions .btn-outline:hover {
532	    background: #FDF8F0;
533	    color: #6B4226;
534	    border-color: #FDF8F0;
535	}
536	
537	/* Hero decoration */
538	.hero-decoration {
539	    position: relative;
540	    display: flex;
541	    justify-content: center;
542	    align-items: center;
543	}
544	
545	.hero-circle {
546	    width: 320px;
547	    height: 320px;
548	    border-radius: 50%;
549	    background: radial-gradient(circle, rgba(198, 134, 66, 0.15) 0%, transparent 70%);
550	    border: 2px solid rgba(198, 134, 66, 0.2);
551	    animation: pulse 4s ease-in-out infinite;
552	}
553	
554	.hero-circle-small {
555	    position: absolute;
556	    width: 200px;
557	    height: 200px;
558	    border-radius: 50%;
559	    border: 1px solid rgba(198, 134, 66, 0.15);
560	    animation: pulse 4s ease-in-out infinite 1s;
561	}
562	
563	.hero-icon {
564	    position: absolute;
565	    font-size: 4rem;
566	    color: rgba(212, 165, 106, 0.6);
567	    animation: float 6s ease-in-out infinite;
568	}
569	
570	@keyframes pulse {
571	    0%, 100% { transform: scale(1); opacity: 0.6; }
572	    50% { transform: scale(1.05); opacity: 1; }
573	}
574	
575	@keyframes float {
576	    0%, 100% { transform: translateY(0); }
577	    50% { transform: translateY(-15px); }
578	}
579	
580	/* ========================================
581	   TENTANG
582	   ======================================== */
583	.about-grid {
584	    display: grid;
585	    grid-template-columns: 1fr 1fr;
586	    gap: 3rem;
587	    align-items: center;
588	}
589	
590	.about-text p {
591	    color: #5D4A3A;
592	    margin-bottom: 1rem;
593	    font-size: 0.95rem;
594	}
595	
596	.about-text p strong {
597	    color: #6B4226;
598	}
599	
600	.about-values {
601	    display: grid;
602	    grid-template-columns: 1fr 1fr;
603	    gap: 1rem;
604	    margin-top: 2rem;
605	}
606	
607	.value-item {
608	    display: flex;
609	    align-items: center;
610	    gap: 0.75rem;
611	    padding: 0.75rem 1rem;
612	    background: rgba(107, 66, 38, 0.06);
613	    border-radius: 12px;
614	    font-size: 0.85rem;
615	    font-weight: 500;
616	    color: #6B4226;
617	    transition: all 0.3s ease;
618	}
619	
620	.value-item i {
621	    color: #C68642;
622	    font-size: 1.1rem;
623	}
624	
625	.value-item:hover {
626	    background: rgba(107, 66, 38, 0.12);
627	    transform: translateY(-2px);
628	}
629	
630	.about-image {
631	    display: flex;
632	    justify-content: center;
633	    align-items: center;
634	}
635	
636	.about-img-box {
637	    width: 320px;
638	    height: 380px;
639	    border-radius: 20px;
640	    background-size: cover;
641	    background-position: center;
642	    position: relative;
643	    overflow: hidden;
644	    box-shadow: 0 20px 40px rgba(44, 24, 16, 0.15);
645	    transition: transform 0.4s ease;
646	}
647	
648	.about-img-box:hover {
649	    transform: scale(1.02);
650	}
651	
652	.about-img-overlay {
653	    position: absolute;
654	    inset: 0;
655	    background: linear-gradient(to top, rgba(44, 24, 16, 0.6) 0%, transparent 40%);
656	    border-radius: 20px;
657	}
658	
659	.about-img-content {
660	    position: absolute;
661	    bottom: 0;
662	    left: 0;
663	    right: 0;
664	    padding: 2rem;
665	    display: flex;
666	    flex-direction: column;
667	    align-items: center;
668	    gap: 0.5rem;
669	}
670	
671	.about-img-content i {
672	    font-size: 2.5rem;
673	    color: rgba(255, 255, 255, 0.8);
674	}
675	
676	.about-img-label {
677	    font-family: 'Playfair Display', serif;
678	    font-size: 1.2rem;
679	    color: #fff;
680	    font-weight: 600;
681	}
682	
683	/* About stats */
684	.about-stats {
685	    display: grid;
686	    grid-template-columns: repeat(4, 1fr);
687	    gap: 0.75rem;
688	    margin-top: 2rem;
689	}
690	.stat-item {
691	    text-align: center;
692	    padding: 0.75rem 0.5rem;
693	    background: rgba(107, 66, 38, 0.06);
694	    border-radius: 12px;
695	    transition: all 0.3s ease;
696	}
697	.stat-item:hover {
698	    background: rgba(107, 66, 38, 0.12);
699	    transform: translateY(-3px);
700	}
701	.stat-number {
702	    display: block;
703	    font-family: 'Playfair Display', serif;
704	    font-size: 1.6rem;
705	    font-weight: 700;
706	    color: #6B4226;
707	}
708	.stat-label {
709	    font-size: 0.7rem;
710	    color: #7D6B5A;
711	    margin-top: 0.2rem;
712	}
713	
714	/* Service extra features */
715	.service-features {
716	    list-style: none;
717	    margin-top: 1rem;
718	    text-align: left;
719	}
720	.service-features li {
721	    font-size: 0.8rem;
722	    color: #7D6B5A;
723	    padding: 0.3rem 0;
724	    display: flex;
725	    align-items: center;
726	    gap: 0.4rem;
727	}
728	.service-features li i {
729	    color: #C68642;
730	    font-size: 0.7rem;
731	}
732	
733	/* Gallery filter tags */
734	.gallery-tags {
735	    display: flex;
736	    justify-content: center;
737	    flex-wrap: wrap;
738	    gap: 0.5rem;
739	    margin-bottom: 2rem;
740	}
741	.gallery-tag {
742	    padding: 0.4rem 1rem;
743	    border-radius: 50px;
744	    font-size: 0.8rem;
745	    border: 1px solid rgba(107, 66, 38, 0.15);
746	    background: transparent;
747	    color: #7D6B5A;
748	    cursor: pointer;
749	    transition: all 0.3s ease;
750	}
751	.gallery-tag:hover,
752	.gallery-tag.active {
